public class CoverageCalculationFunction
        implements BackgroundFunction<PubSubMessage> {

    private final CoverageCalculator calculator =
        new CoverageCalculator();

    @Override
    public void accept(
        PubSubMessage message,
        Context context
    ) {
        String companyId =
            new String(
                Base64.getDecoder().decode(
                    message.getData()
                ),
                StandardCharsets.UTF_8
            );

        calculator.calculateAndStore(companyId);
    }
}
